    release_number_parts = "".join(character if character.isdigit() else " " for character in song["release_date"]).split()
    release_year_candidates = [int(part) for part in release_number_parts if len(part) == 4]
    if release_year_candidates and normalized_genre_key(song["genre"]) in r_and_b_genre_keys and release_year_candidates[0] in allowed_release_years:
        post_add_eligible_ids.append(song["song_id"])
if post_add_song_ids != songs_ready_to_add or post_add_eligible_ids != songs_ready_to_add:
    raise ValueError("Post-mutation song verification did not match the reviewed selection")
if len(add_song_results) != len(songs_ready_to_add):
    raise ValueError("Not every reviewed song produced an addition response")
if any("message" not in result["response"] for result in add_song_results):
