The saved details can now be filtered to the requested R&B genre and the two allowed release years, while retaining only IDs derived from actual recommendations; the exact playlist title is also reviewed before creation.

```python
def normalized_genre_key(value):
    return "".join(character for character in value.casefold() if character.isalnum())

r_and_b_genre_keys = {"rb", "rnb", "rhythmandblues"}
selected_songs = []
selected_song_summaries = []
for song in recommended_song_details:
    release_number_parts = "".join(character if character.isdigit() else " " for character in song["release_date"]).split()
    release_year_candidates = [int(part) for part in release_number_parts if len(part) == 4]
    if release_year_candidates:
        release_year = release_year_candidates[0]
        if normalized_genre_key(song["genre"]) in r_and_b_genre_keys and release_year in allowed_release_years:
            selected_songs.append(song)
            selected_song_summaries.append({"song_id": song["song_id"], "title": song["title"], "genre": song["genre"], "release_year": release_year})
selected_song_ids = [song["song_id"] for song in selected_songs]
playlist_title = "Spotify R&B Recommendations"
print({"playlist_title": playlist_title, "selected_song_count": len(selected_song_ids), "selected_songs": selected_song_summaries})
