After the mutations, every added song must be re-queried and checked again, while the playlist-creation and per-song addition responses are assembled as public postcondition evidence.

```python
post_add_song_details = []
for song_id in songs_ready_to_add:
    post_add_song_details.append(apis.spotify.show_song(song_id=song_id))
post_add_song_ids = [song["song_id"] for song in post_add_song_details]
post_add_eligible_ids = []
for song in post_add_song_details:
    release_number_parts = "".join(character if character.isdigit() else " " for character in song["release_date"]).split()
    release_year_candidates = [int(part) for part in release_number_parts if len(part) == 4]
    if release_year_candidates and normalized_genre_key(song["genre"]) in r_and_b_genre_keys and release_year_candidates[0] in allowed_release_years:
        post_add_eligible_ids.append(song["song_id"])
if post_add_song_ids != songs_ready_to_add or post_add_eligible_ids != songs_ready_to_add:
    raise ValueError("Post-mutation song verification did not match the reviewed selection")
if len(add_song_results) != len(songs_ready_to_add):
    raise ValueError("Not every reviewed song produced an addition response")
if any("message" not in result["response"] for result in add_song_results):
    raise ValueError("An addition response is missing its public message")
verification_evidence = {
    "playlist": {"playlist_id": playlist_id, "title": playlist_title, "creation_message": created_playlist["message"]},
    "additions": [{"song_id": result["song_id"], "message": result["response"]["message"]} for result in add_song_results],
    "refetched_songs": [{"song_id": song["song_id"], "title": song["title"], "genre": song["genre"], "release_date": song["release_date"]} for song in post_add_song_details],
}
print(verification_evidence)
